def priority_fn_v1(item_size, open_bin_remaining_capacities, capacity):
    """Improved version of `priority_fn_v0`."""
    rem = np.asarray(open_bin_remaining_capacities)
    if rem.size == 0:
        return np.array([0.0])

    gaps = rem - item_size
    # Prioritise exact or very tight fits, while penalising awkward residual gaps.
    # Scores reward reducing waste and keeping remaining space usable.
    scores = -gaps.astype(float)
    scores = np.where(gaps == 0, scores + capacity, scores)

    # Opening a new bin should be least preferred compared to any valid fit.
    new_bin_score = -capacity - 1.0
    return np.append(scores, new_bin_score)
